export const zErrorLinks = z.object({
    about: z.string().optional(),
    associated: z.union([
        z.string(),
        z.object({
            href: z.string().optional(),
            meta: z.object({
                source: z.string().optional()
            }).optional()
        })
    ]).optional()
});

export const zErrorResponse = z.object({
    errors: z.array(z.object({
        id: z.string().optional(),
        status: z.string(),
        code: z.string(),
        title: z.string(),
        detail: z.string(),
        source: z.union([
            zErrorSourcePointer,
            zErrorSourceParameter
        ]).optional(),
        links: zErrorLinks.optional(),
        meta: z.record(z.string(), z.unknown()).optional()
    })).optional()
});

